RKfill("nextjs",[{"b":["<b>Next.js</b> adalah framework React dari Vercel untuk membangun aplikasi web lengkap. React sendiri hanya pustaka UI; Next.js menambahkan <b>routing berbasis folder</b>, <b>rendering di server</b> (SSR dan statis) yang bagus untuk SEO dan kecepatan, pengambilan data, optimasi gambar dan font, serta API di proyek yang sama.","Next.js modern memakai <b>App Router</b> (folder <code>app/</code>) dengan <b>React Server Components</b>: komponen berjalan di server secara bawaan, sehingga JavaScript yang dikirim ke browser lebih sedikit. Pages Router (folder <code>pages/</code>) masih ada di proyek lama.","Prasyarat: HTML, CSS, JavaScript modern, dan dasar React (komponen, props, state). Selesaikan jalur React dan TypeScript di Ruang Kode jika belum."],"lang":"bash","code":"npx create-next-app@latest tokoku\n# pilih: TypeScript Yes, ESLint Yes, Tailwind CSS Yes,\n#        src/ directory No, App Router Yes, Turbopack Yes\ncd tokoku\nnpm run dev","out":"  ▲ Next.js 15.5.4 (Turbopack)\n  - Local:        http://localhost:3000\n  - Network:      http://192.168.1.7:3000\n\n ✓ Starting...\n ✓ Ready in 1186ms","run":false,"tb":[{"c":"React saja vs Next.js","h":["Kebutuhan","React (Vite)","Next.js"],"r":[["Routing","Pasang React Router","Bawaan, berbasis folder"],["SEO dan HTML awal","Kosong sampai JS jalan","HTML dirender di server"],["Ambil data","useEffect atau pustaka","async di Server Component"],["Backend kecil","Proyek terpisah","Route Handler dan Server Action"],["Gambar","Manual","next/image (ukuran, lazy, format modern)"]]}],"pts":["Next.js = React + routing + rendering server + optimasi.","App Router dan Server Components adalah standar baru.","Butuh dasar React dulu."],"q":[["Keunggulan utama render di server untuk toko online?",["HTML langsung berisi konten sehingga bagus untuk SEO dan cepat tampil","Tidak butuh internet","Tidak perlu CSS"],0,"Mesin pencari dan pengguna langsung melihat konten."]],"deep":{"ist":[["Meta-framework","Framework di atas React yang menyediakan routing, rendering server, dan build."],["SSR / SSG / ISR","Render per request, saat build, atau statis yang diperbarui berkala."],["SEO","HTML sudah berisi konten saat dikirim, sehingga mudah dibaca mesin pencari."],["Turbopack","Bundler berbasis Rust yang menjadi default dev dan build di Next.js 15/16."],["Full-stack React","UI dan endpoint server dalam satu proyek."]],"cx":[{"t":"Membandingkan strategi rendering","b":"Angka TTFB hanya ilustrasi. Di Next.js, satu aplikasi bisa mencampur semua strategi per halaman.","code":"type Strategi = { nama: string; kapanHtmlDibuat: string; ttfbMs: number; dataSegar: string; contoh: string };\nconst s: Strategi[] = [\n  { nama: \"CSR (SPA)\", kapanHtmlDibuat: \"di browser\", ttfbMs: 50, dataSegar: \"ya\", contoh: \"dasbor admin internal\" },\n  { nama: \"SSR\", kapanHtmlDibuat: \"tiap request\", ttfbMs: 300, dataSegar: \"ya\", contoh: \"halaman akun, hasil pencarian\" },\n  { nama: \"SSG\", kapanHtmlDibuat: \"saat build\", ttfbMs: 30, dataSegar: \"sampai build ulang\", contoh: \"blog, dokumentasi\" },\n  { nama: \"ISR\", kapanHtmlDibuat: \"build + berkala\", ttfbMs: 30, dataSegar: \"maks N detik\", contoh: \"katalog produk\" },\n];\nconsole.log(\"Strategi\".padEnd(10), \"HTML dibuat\".padEnd(16), \"TTFB\".padStart(6), \" Data segar\".padEnd(20), \"Cocok untuk\");\nfor (const x of s) console.log(x.nama.padEnd(10), x.kapanHtmlDibuat.padEnd(16), (x.ttfbMs + \"ms\").padStart(6), \" \" + x.dataSegar.padEnd(19), x.contoh);","lang":"ts","out":"Strategi   HTML dibuat        TTFB  Data segar          Cocok untuk\nCSR (SPA)  di browser         50ms  ya                  dasbor admin internal\nSSR        tiap request      300ms  ya                  halaman akun, hasil pencarian\nSSG        saat build         30ms  sampai build ulang  blog, dokumentasi\nISR        build + berkala    30ms  maks N detik        katalog produk"},{"t":"Membuat proyek","code":"npx create-next-app@latest toko --ts --tailwind --eslint --app --src-dir\ncd toko && npm run dev          # http://localhost:3000\n\nsrc/app/\n├── layout.tsx      # kerangka HTML semua halaman\n├── page.tsx        # halaman \"/\"\n└── globals.css","lang":"bash"}]}},{"b":["Di App Router, <b>folder adalah rute</b>. File <code>page.tsx</code> membuat rute bisa dibuka; <code>app/produk/page.tsx</code> menjadi <code>/produk</code>. File <code>layout.tsx</code> membungkus halaman di folder itu dan turunannya, dan <b>tidak di-render ulang</b> saat berpindah halaman, cocok untuk navbar dan sidebar.","File khusus lain: <code>loading.tsx</code> (tampilan saat memuat), <code>error.tsx</code> (penanganan error), <code>not-found.tsx</code> (404). Folder dalam kurung seperti <code>(toko)</code> mengelompokkan rute tanpa memengaruhi URL.","Pindah halaman dengan komponen <code>&lt;Link href=\"/produk\"&gt;</code> (tanpa memuat ulang halaman dan otomatis prefetch). Untuk navigasi lewat kode, pakai <code>useRouter()</code> dari <code>next/navigation</code> di Client Component."],"lang":"tsx","code":"// app/layout.tsx\nimport Link from 'next/link';\nimport './globals.css';\n\nexport const metadata = { title: 'Tokoku', description: 'Kopi Nusantara' };\n\nexport default function RootLayout({ children }: { children: React.ReactNode }) {\n  return (\n    <html lang=\"id\">\n      <body>\n        <nav className=\"flex gap-4 p-4\">\n          <Link href=\"/\">Beranda</Link>\n          <Link href=\"/produk\">Produk</Link>\n        </nav>\n        {children}\n      </body>\n    </html>\n  );\n}\n\n// app/produk/page.tsx  ->  /produk\nexport default function HalamanProduk() {\n  return <h1 className=\"text-2xl font-bold\">Semua produk</h1>;\n}","tb":[{"c":"File khusus App Router","h":["File","Fungsi"],"r":[["page.tsx","Isi halaman, membuat rute bisa diakses"],["layout.tsx","Kerangka bersama, tetap saat navigasi"],["loading.tsx","UI saat memuat (Suspense)"],["error.tsx","UI saat error, harus Client Component"],["not-found.tsx","Halaman 404"],["route.ts","API endpoint (Route Handler)"]]}],"pts":["Folder = rute, page.tsx = halaman.","layout.tsx membungkus dan tidak di-render ulang.","Link untuk navigasi tanpa reload."],"q":[["File yang membuat URL /tentang?",["app/tentang/page.tsx","app/tentang.tsx","pages/app/tentang/layout.tsx"],0,"Folder tentang berisi page.tsx."]],"deep":{"ist":[["File-based routing","Folder di app/ menjadi segmen URL; page.tsx membuatnya dapat diakses."],["layout.tsx","UI bersama yang tetap ada saat berpindah halaman (tidak render ulang)."],["<Link>","Navigasi sisi klien dengan prefetch otomatis."],["Route group (folder)","Folder dalam tanda kurung untuk mengelompokkan tanpa memengaruhi URL."],["Special files","loading.tsx, error.tsx, not-found.tsx, template.tsx."]],"cx":[{"t":"Struktur folder dan layout bersarang","code":"app/\n├── layout.tsx                 -> <html> root, font, header\n├── page.tsx                   -> /\n├── (toko)/\n│   ├── layout.tsx             -> layout dengan sidebar kategori\n│   ├── produk/page.tsx        -> /produk\n│   └── keranjang/page.tsx     -> /keranjang\n├── (akun)/akun/page.tsx       -> /akun\n└── not-found.tsx\n\n// app/layout.tsx\nimport Link from \"next/link\";\nexport default function RootLayout({ children }: { children: React.ReactNode }) {\n  return (\n    <html lang=\"id\">\n      <body>\n        <header>\n          <Link href=\"/\">Beranda</Link>\n          <Link href=\"/produk\">Produk</Link>\n          <Link href=\"/keranjang\" prefetch={false}>Keranjang</Link>\n        </header>\n        <main>{children}</main>\n      </body>\n    </html>\n  );\n}","lang":"tsx"},{"t":"Dari daftar file ke tabel rute","code":"const file = [\n  \"app/page.tsx\", \"app/(toko)/produk/page.tsx\", \"app/(toko)/produk/[slug]/page.tsx\",\n  \"app/(toko)/keranjang/page.tsx\", \"app/blog/[...slug]/page.tsx\", \"app/api/produk/route.ts\",\n  \"app/(toko)/layout.tsx\", \"app/_komponen/Tombol.tsx\",\n];\nfor (const f of file) {\n  const m = f.match(/^app\\/(.*?)\\/?(page\\.tsx|route\\.ts)$/);\n  if (!m) { console.log(f.padEnd(36), \"-> bukan rute (layout/privat)\"); continue; }\n  const url = \"/\" + m[1].split(\"/\").filter((s) => s && !/^\\(.*\\)$/.test(s) && !s.startsWith(\"_\"))\n    .map((s) => s.replace(/^\\[\\.\\.\\.(\\w+)\\]$/, \":$1*\").replace(/^\\[(\\w+)\\]$/, \":$1\")).join(\"/\");\n  console.log(f.padEnd(36), \"->\", url, m[2] === \"route.ts\" ? \"(API)\" : \"\");\n}","lang":"ts","out":"app/page.tsx                         -> / \napp/(toko)/produk/page.tsx           -> /produk \napp/(toko)/produk/[slug]/page.tsx    -> /produk/:slug \napp/(toko)/keranjang/page.tsx        -> /keranjang \napp/blog/[...slug]/page.tsx          -> /blog/:slug* \napp/api/produk/route.ts              -> /api/produk (API)\napp/(toko)/layout.tsx                -> bukan rute (layout/privat)\napp/_komponen/Tombol.tsx             -> bukan rute (layout/privat)"}]}},{"b":["Folder dengan kurung siku seperti <code>app/produk/[slug]/page.tsx</code> menangkap bagian URL apa pun: <code>/produk/kopi-gayo</code> memberi <code>params.slug = 'kopi-gayo'</code>. Di Next.js 15, <code>params</code> adalah Promise sehingga perlu di-<code>await</code>.","<code>generateStaticParams</code> membuat halaman statis untuk daftar slug saat build, sehingga halaman produk populer siap seketika. Panggil <code>notFound()</code> jika data tidak ada.","Untuk SEO, ekspor <code>generateMetadata</code> agar setiap halaman punya judul, deskripsi, dan gambar Open Graph sendiri."],"lang":"tsx","code":"// app/produk/[slug]/page.tsx\nimport { notFound } from 'next/navigation';\nimport { ambilProduk, semuaSlug } from '@/lib/produk';\n\nexport async function generateStaticParams() {\n  return (await semuaSlug()).map((slug) => ({ slug }));\n}\n\nexport async function generateMetadata({ params }: { params: Promise<{ slug: string }> }) {\n  const p = await ambilProduk((await params).slug);\n  return { title: p ? `${p.nama} | Tokoku` : 'Tidak ditemukan' };\n}\n\nexport default async function DetailProduk({ params }: { params: Promise<{ slug: string }> }) {\n  const { slug } = await params;\n  const p = await ambilProduk(slug);\n  if (!p) notFound();\n  return (\n    <main className=\"p-4\">\n      <h1 className=\"text-2xl font-bold\">{p.nama}</h1>\n      <p>Rp{p.harga.toLocaleString('id-ID')}</p>\n    </main>\n  );\n}","so":[{"q":"Buat halaman <code>app/kategori/[nama]/page.tsx</code> yang menampilkan judul \"Kategori: {nama}\".","h":"Ambil nama dari params yang di-await.","a":"export default async function Kategori({ params }: { params: Promise<{ nama: string }> }) {\n  const { nama } = await params;\n  return <h1>Kategori: {decodeURIComponent(nama)}</h1>;\n}","lang":"tsx"}],"pts":["[slug] = segmen dinamis.","params di-await di Next.js 15.","generateStaticParams dan generateMetadata."],"q":[["File untuk URL /blog/2026/belajar-next?",["app/blog/[tahun]/[slug]/page.tsx","app/blog/[slug].tsx","app/[blog]/page.tsx"],0,"Dua segmen dinamis bersarang."]],"deep":{"ist":[["Dynamic segment [slug]","Folder [slug] menerima nilai apa pun dari URL."],["generateStaticParams","Daftar parameter yang di-render statis saat build."],["generateMetadata","Membuat title, description, dan Open Graph per halaman."],["Open Graph","Metadata pratinjau tautan di WhatsApp, X, LinkedIn."],["Canonical URL","Alamat utama halaman agar tidak dianggap konten duplikat."]],"cx":[{"t":"Halaman produk dengan metadata dinamis","code":"// app/produk/[slug]/page.tsx\nimport type { Metadata } from \"next\";\nimport { notFound } from \"next/navigation\";\n\ntype Props = { params: Promise<{ slug: string }> };\n\nexport async function generateStaticParams() {\n  const produk = await db.produk.findMany({ select: { slug: true }, take: 100 });\n  return produk.map((p) => ({ slug: p.slug }));           // 100 terlaris dibuat saat build\n}\n\nexport async function generateMetadata({ params }: Props): Promise<Metadata> {\n  const p = await ambilProduk((await params).slug);\n  if (!p) return {};\n  return {\n    title: `${p.nama} | Toko Kopi`,\n    description: p.ringkasan.slice(0, 155),\n    alternates: { canonical: `/produk/${p.slug}` },\n    openGraph: { images: [{ url: p.gambar, width: 1200, height: 630 }] },\n  };\n}\n\nexport default async function Halaman({ params }: Props) {\n  const p = await ambilProduk((await params).slug);\n  if (!p) notFound();\n  return <h1>{p.nama}</h1>;\n}","lang":"tsx"},{"t":"Membuat slug dan memotong deskripsi untuk SEO","code":"const slugify = (s: string) => s.normalize(\"NFD\").replace(/[̀-ͯ]/g, \"\").toLowerCase()\n  .replace(/&/g, \" dan \").replace(/[^a-z0-9]+/g, \"-\").replace(/^-|-$/g, \"\");\nconst potong = (s: string, n = 155) => (s.length <= n ? s : s.slice(0, s.lastIndexOf(\" \", n - 1)) + \"…\");\n\nconst produk = [\"Kopi Arabika Gayo 250g\", \"Teh & Gula Aren — Paket Hemat\", \"Café Crème Spécial\"];\nproduk.forEach((p) => console.log(p.padEnd(32), \"->\", \"/produk/\" + slugify(p)));\nconst desk = \"Kopi arabika dari dataran tinggi Gayo, Aceh, diproses full wash dan disangrai medium. Rasa cokelat, jeruk, dan karamel dengan keasaman sedang yang cocok untuk V60 maupun espresso harian.\";\nconst d = potong(desk);\nconsole.log(d.length, \"karakter:\", d);","lang":"ts","out":"Kopi Arabika Gayo 250g           -> /produk/kopi-arabika-gayo-250g\nTeh & Gula Aren — Paket Hemat    -> /produk/teh-dan-gula-aren-paket-hemat\nCafé Crème Spécial               -> /produk/cafe-creme-special\n153 karakter: Kopi arabika dari dataran tinggi Gayo, Aceh, diproses full wash dan disangrai medium. Rasa cokelat, jeruk, dan karamel dengan keasaman sedang yang cocok…"}]}},{"b":["Di App Router, semua komponen adalah <b>Server Component</b> secara bawaan: dijalankan di server, boleh <code>async</code>, bisa langsung membaca database atau rahasia API, dan kodenya <b>tidak dikirim</b> ke browser.","Tambahkan <code>'use client'</code> di baris pertama file untuk membuat <b>Client Component</b> jika butuh interaktivitas: <code>useState</code>, <code>useEffect</code>, event seperti <code>onClick</code>, atau API browser seperti <code>localStorage</code>.","Prinsipnya: biarkan sebanyak mungkin di server, dan jadikan Client Component hanya \"pulau\" kecil yang interaktif, misalnya tombol tambah ke keranjang di dalam halaman produk yang dirender server."],"lang":"tsx","code":"// components/TombolKeranjang.tsx\n'use client';\nimport { useState } from 'react';\n\nexport default function TombolKeranjang({ nama }: { nama: string }) {\n  const [jumlah, setJumlah] = useState(0);\n  return (\n    <button onClick={() => setJumlah(jumlah + 1)} className=\"rounded bg-amber-700 px-4 py-2 text-white\">\n      Tambah {nama} ({jumlah})\n    </button>\n  );\n}\n\n// app/produk/[slug]/page.tsx  (Server Component)\nimport TombolKeranjang from '@/components/TombolKeranjang';\nexport default async function Detail() {\n  const p = await db.produk.findFirst();   // langsung ke database, aman\n  return (\n    <main>\n      <h1>{p.nama}</h1>\n      <TombolKeranjang nama={p.nama} />\n    </main>\n  );\n}","tb":[{"c":"Kapan memakai yang mana","h":["Kebutuhan","Server","Client"],"r":[["Ambil data dari database atau API rahasia","Ya","Tidak"],["useState, useEffect","Tidak","Ya"],["onClick, onChange","Tidak","Ya"],["localStorage, window","Tidak","Ya"],["Mengurangi JS di browser","Ya","Tidak"],["async/await langsung di komponen","Ya","Tidak"]]}],"pts":["Bawaan: Server Component.","'use client' untuk state, event, API browser.","Jadikan Client Component sekecil mungkin."],"q":[["Komponen yang memakai useState harus?",["Diberi 'use client'","Dibuat async","Diletakkan di folder pages"],0,"Hook state hanya di client."],["Kenapa membaca database di Server Component aman?",["Kodenya tidak dikirim ke browser","Database otomatis terenkripsi","Next.js menyembunyikan semua variabel"],0,"Kode tetap di server."]],"deep":{"ist":[["React Server Component (RSC)","Default di App Router: berjalan di server, boleh async, akses DB langsung, tanpa JS ke klien."],["\"use client\"","Direktif di awal file yang menjadikannya Client Component (boleh state, effect, event)."],["Bundle size","Kode Server Component tidak ikut dikirim ke browser."],["server-only","Paket penanda agar modul rahasia gagal di-build bila terimpor ke klien."]],"cx":[{"t":"Halaman server dengan tombol interaktif kecil","code":"// app/produk/page.tsx  (Server Component: default)\nimport \"server-only\";\nimport { TombolTambah } from \"./TombolTambah\";\n\nexport default async function Produk() {\n  const daftar = await db.produk.findMany({ orderBy: { terjual: \"desc\" }, take: 12 });  // query langsung\n  return (\n    <ul className=\"grid\">\n      {daftar.map((p) => (\n        <li key={p.id}>\n          <h3>{p.nama}</h3>\n          <p>Rp{p.harga.toLocaleString(\"id-ID\")}</p>\n          <TombolTambah id={p.id} />      {/* hanya bagian ini yang butuh JS */}\n        </li>\n      ))}\n    </ul>\n  );\n}\n\n// app/produk/TombolTambah.tsx\n\"use client\";\nimport { useState } from \"react\";\nexport function TombolTambah({ id }: { id: number }) {\n  const [ok, setOk] = useState(false);\n  return <button onClick={() => { tambahKeKeranjang(id); setOk(true); }}>{ok ? \"✓ Ditambahkan\" : \"Tambah\"}</button>;\n}","lang":"tsx"}]}},{"b":["Begitu file diberi <code>'use client'</code>, semua yang <b>di-import</b> oleh file itu ikut menjadi kode client. Karena itu letakkan <code>'use client'</code> sedalam mungkin di pohon komponen.","Server Component tetap bisa dirender <b>di dalam</b> Client Component jika dikirim sebagai <code>children</code> atau prop. Contoh: penyedia tema (Client) membungkus halaman (Server).","Props dari server ke client harus bisa diserialisasi (string, angka, objek biasa, array). Fungsi biasa tidak bisa dikirim, kecuali Server Action."],"lang":"tsx","code":"// app/providers.tsx\n'use client';\nimport { ThemeProvider } from 'next-themes';\nexport function Providers({ children }: { children: React.ReactNode }) {\n  return <ThemeProvider attribute=\"class\">{children}</ThemeProvider>;\n}\n\n// app/layout.tsx (Server)\nimport { Providers } from './providers';\nexport default function RootLayout({ children }: { children: React.ReactNode }) {\n  return (\n    <html lang=\"id\" suppressHydrationWarning>\n      <body><Providers>{children}</Providers></body>   {/* children tetap Server Component */}\n    </html>\n  );\n}","pts":["'use client' sedalam mungkin.","Server Component boleh jadi children dari Client Component.","Props harus bisa diserialisasi."],"q":[["Akibat menaruh 'use client' di layout paling atas?",["Hampir semua komponen ikut menjadi kode client","Halaman menjadi lebih cepat","Tidak ada pengaruh"],0,"Batas client mencakup semua yang di-import."]],"deep":{"ist":[["Client boundary","File \"use client\" dan semua yang diimpornya menjadi bagian bundle klien."],["Children pattern","Client Component menerima Server Component lewat children agar tetap di server."],["Serializable props","Props dari server ke klien harus bisa di-JSON-kan (tanpa fungsi, kelas, Date mentah)."],["Push client down","Letakkan \"use client\" serendah mungkin di pohon komponen."]],"cx":[{"t":"Sidebar interaktif yang membungkus konten server","code":"// app/dasbor/Sidebar.tsx\n\"use client\";\nimport { useState, type ReactNode } from \"react\";\nexport function Sidebar({ children }: { children: ReactNode }) {\n  const [buka, setBuka] = useState(true);\n  return (\n    <aside data-buka={buka}>\n      <button onClick={() => setBuka(!buka)} aria-expanded={buka}>Menu</button>\n      {buka && children}          {/* children tetap Server Component */}\n    </aside>\n  );\n}\n\n// app/dasbor/layout.tsx  (server)\nexport default async function Layout({ children }: { children: ReactNode }) {\n  const menu = await ambilMenuSesuaiPeran();      // data di server\n  return (\n    <div className=\"dasbor\">\n      <Sidebar><NavServer menu={menu} /></Sidebar>\n      {children}\n    </div>\n  );\n}\n\n// SALAH: mengimpor Server Component di dalam file \"use client\"\n// \"use client\"; import NavServer from \"./NavServer\";  -> NavServer ikut menjadi klien","lang":"tsx"},{"t":"Memeriksa apakah props aman dikirim ke klien","code":"function cekSerializable(nilai: unknown, jalur = \"props\"): string[] {\n  if (nilai === null || [\"string\", \"number\", \"boolean\", \"undefined\"].includes(typeof nilai)) return [];\n  if (typeof nilai === \"function\") return [`${jalur}: fungsi tidak bisa dikirim (pakai Server Action)`];\n  if (nilai instanceof Date) return [`${jalur}: Date sebaiknya dikirim sebagai string ISO`];\n  if (nilai instanceof Map || nilai instanceof Set) return [];\n  if (Array.isArray(nilai)) return nilai.flatMap((v, i) => cekSerializable(v, `${jalur}[${i}]`));\n  if (Object.getPrototypeOf(nilai) !== Object.prototype) return [`${jalur}: instance kelas tidak didukung`];\n  return Object.entries(nilai as object).flatMap(([k, v]) => cekSerializable(v, `${jalur}.${k}`));\n}\nclass Uang { constructor(public n: number) {} }\nconst props = { nama: \"Kopi\", harga: 45000, dibuat: new Date(), onBeli: () => {}, diskon: new Uang(5000), tag: [\"baru\"] };\nconst masalah = cekSerializable(props);\nconsole.log(masalah.length ? masalah.join(\"\\n\") : \"semua aman\");","lang":"ts","out":"props.dibuat: Date sebaiknya dikirim sebagai string ISO\nprops.onBeli: fungsi tidak bisa dikirim (pakai Server Action)\nprops.diskon: instance kelas tidak didukung"}]}},{"b":["<b>Hydration</b> adalah proses React di browser \"menghidupkan\" HTML dari server dengan menempelkan event handler. Jika HTML dari server berbeda dengan render pertama di client, muncul <b>hydration mismatch</b>.","Penyebab umum: memakai <code>Date.now()</code> atau <code>Math.random()</code> saat render, membaca <code>window</code> atau <code>localStorage</code> langsung di render, dan format tanggal yang bergantung zona waktu browser.","Solusi: baca nilai browser di <code>useEffect</code>, kirim nilai yang sama dari server, atau muat komponen khusus browser dengan <code>dynamic(() =&gt; import(...), { ssr: false })</code>."],"lang":"tsx","code":"'use client';\nimport { useEffect, useState } from 'react';\n\n// salah: server dan browser bisa berbeda\n// return <p>{localStorage.getItem('nama')}</p>;\n\nexport default function Sapaan() {\n  const [nama, setNama] = useState<string | null>(null);\n  useEffect(() => {\n    setNama(localStorage.getItem('nama'));\n  }, []);\n  return <p>Halo, {nama ?? 'tamu'}</p>;\n}","out":"Error: Hydration failed because the server rendered HTML didn't match the client.\n  + Halo, Rina\n  - Halo, tamu","run":false,"pts":["Hydration menempelkan interaksi ke HTML server.","Hindari nilai acak, waktu, dan window saat render.","Baca API browser di useEffect."],"q":[["Penyebab hydration mismatch?",["Memakai Math.random() saat render","Memakai Link","Memakai Tailwind"],0,"Hasil server dan client berbeda."]],"deep":{"ist":[["Hydration","React di browser \"menghidupkan\" HTML dari server dengan memasang event handler."],["Hydration mismatch","HTML server berbeda dengan render pertama klien; React memberi peringatan dan merender ulang."],["suppressHydrationWarning","Pengecualian untuk nilai yang memang berbeda (misalnya jam)."],["Selective hydration","Bagian dalam Suspense dihidupkan bertahap sesuai prioritas."]],"cx":[{"t":"Penyebab mismatch dan perbaikannya","code":"// SALAH: nilai berbeda di server dan browser\nexport function Salam() {\n  const jam = new Date().getHours();                  // zona waktu server (UTC) ≠ browser (WIB)\n  return <p>{jam < 12 ? \"Selamat pagi\" : \"Selamat siang\"}</p>;\n}\n// SALAH: akses window saat render\nconst lebar = typeof window !== \"undefined\" ? window.innerWidth : 0;\n\n// BENAR: tunda nilai khusus browser sampai setelah mount\n\"use client\";\nimport { useEffect, useState } from \"react\";\nexport function SalamAman() {\n  const [teks, setTeks] = useState<string | null>(null);\n  useEffect(() => setTeks(new Date().getHours() < 12 ? \"Selamat pagi\" : \"Selamat siang\"), []);\n  return <p>{teks ?? \"Halo\"}</p>;\n}\n\n// BENAR: komponen yang hanya jalan di browser\nimport dynamic from \"next/dynamic\";\nconst Peta = dynamic(() => import(\"./Peta\"), { ssr: false, loading: () => <div className=\"skeleton h-80\" /> });\n\n// Penyebab lain: <p> di dalam <p>, <div> di dalam <p>, ekstensi browser yang menyisipkan atribut","lang":"tsx"},{"t":"Kenapa jam server dan browser berbeda","code":"const momen = new Date(Date.UTC(2026, 10, 19, 4, 30));  // 04:30 UTC\nconst jamDi = (tz: string) => Number(new Intl.DateTimeFormat(\"en-GB\", { hour: \"numeric\", hourCycle: \"h23\", timeZone: tz }).format(momen));\nconst salam = (j: number) => (j < 11 ? \"Selamat pagi\" : j < 15 ? \"Selamat siang\" : \"Selamat sore\");\nconst server = jamDi(\"UTC\"), browser = jamDi(\"Asia/Jakarta\");\nconsole.log(`server (UTC) jam ${server}  -> \"${salam(server)}\"`);\nconsole.log(`browser (WIB) jam ${browser} -> \"${salam(browser)}\"`);\nconsole.log(salam(server) === salam(browser) ? \"cocok\" : \"MISMATCH: teks HTML server berbeda dengan render klien\");","lang":"ts","out":"server (UTC) jam 4  -> \"Selamat pagi\"\nbrowser (WIB) jam 11 -> \"Selamat siang\"\nMISMATCH: teks HTML server berbeda dengan render klien"}]}},{"b":["Di Server Component, ambil data langsung dengan <code>await fetch()</code> atau query database. Tidak perlu <code>useEffect</code>, dan rahasia API tetap di server.","Atur kesegaran data: <code>fetch(url, { next: { revalidate: 60 } })</code> menyimpan hasil dan memperbaruinya paling lama setiap 60 detik (<b>ISR</b>); <code>{ cache: 'no-store' }</code> selalu mengambil data baru; <code>{ next: { tags: ['produk'] } }</code> memberi label agar bisa dihapus dengan <code>revalidateTag('produk')</code> setelah data berubah.","Jalankan beberapa permintaan secara <b>paralel</b> dengan <code>Promise.all</code> agar tidak saling menunggu."],"lang":"tsx","code":"// app/page.tsx\ntype Produk = { id: number; nama: string; harga: number };\n\nasync function ambilProduk(): Promise<Produk[]> {\n  const r = await fetch('https://api.tokoku.id/produk', {\n    next: { revalidate: 60, tags: ['produk'] },\n  });\n  if (!r.ok) throw new Error('Gagal memuat produk');\n  return r.json();\n}\n\nasync function ambilPromo() {\n  const r = await fetch('https://api.tokoku.id/promo', { cache: 'no-store' });\n  return r.json();\n}\n\nexport default async function Beranda() {\n  const [produk, promo] = await Promise.all([ambilProduk(), ambilPromo()]);\n  return (\n    <main>\n      <p className=\"bg-amber-100 p-2\">{promo.teks}</p>\n      <ul>{produk.map((p) => <li key={p.id}>{p.nama}: Rp{p.harga.toLocaleString('id-ID')}</li>)}</ul>\n    </main>\n  );\n}","tb":[{"c":"Strategi rendering","h":["Strategi","Cara","Cocok untuk"],"r":[["Statis (SSG)","Data saat build","Halaman tentang, blog"],["ISR","revalidate: N detik","Katalog produk, berita"],["Dinamis (SSR)","cache: 'no-store', cookies()","Keranjang, dasbor pengguna"],["On-demand","revalidateTag / revalidatePath","Setelah admin mengubah data"]]}],"pts":["await fetch langsung di Server Component.","revalidate, no-store, dan tag.","Promise.all untuk permintaan paralel."],"q":[["Opsi agar daftar produk diperbarui paling lama tiap 5 menit?",["next: { revalidate: 300 }","cache: 'no-store'","revalidate: 5"],0,"Dalam detik."]],"deep":{"ist":[["fetch di Server Component","Ambil data langsung dengan async/await di komponen."],["Data Cache","Hasil fetch dapat di-cache; Next.js 15 tidak lagi meng-cache fetch secara default."],["revalidate","Waktu (detik) sebelum cache dianggap basi (ISR)."],["revalidateTag / revalidatePath","Membuang cache secara on-demand setelah data berubah."],["\"use cache\"","Direktif cache baru (Next.js 16, Cache Components) untuk fungsi atau komponen."]],"cx":[{"t":"Katalog dengan ISR dan revalidasi berbasis tag","code":"// app/produk/page.tsx\nexport const revalidate = 300;                      // ISR: halaman dibuat ulang maksimal tiap 5 menit\n\nasync function ambilProduk() {\n  const r = await fetch(\"https://api.toko.id/produk\", { next: { revalidate: 300, tags: [\"produk\"] } });\n  if (!r.ok) throw new Error(\"Gagal memuat produk\");\n  return r.json() as Promise<Produk[]>;\n}\n\nexport default async function Halaman() {\n  const [produk, kategori] = await Promise.all([ambilProduk(), ambilKategori()]);   // paralel, bukan waterfall\n  return <Katalog produk={produk} kategori={kategori} />;\n}\n\n// app/admin/actions.ts\n\"use server\";\nimport { revalidateTag } from \"next/cache\";\nexport async function ubahHarga(id: number, harga: number) {\n  await db.produk.update({ where: { id }, data: { harga } });\n  revalidateTag(\"produk\");                          // katalog langsung segar\n}","lang":"tsx"},{"t":"Simulasi stale-while-revalidate","b":"Pengunjung pertama setelah kedaluwarsa masih melihat data lama sekali, lalu pengunjung berikutnya mendapat versi baru. Pakai revalidateTag bila perubahan harus langsung terlihat.","code":"function buatCache(revalidateDetik: number, sumber: () => number) {\n  let isi: { nilai: number; waktu: number } | null = null; let generasi = 0;\n  return (t: number) => {\n    if (!isi) { isi = { nilai: sumber(), waktu: t }; return `t=${t}s MISS  -> render baru (harga ${isi.nilai})`; }\n    if (t - isi.waktu < revalidateDetik) return `t=${t}s HIT   -> dari cache (harga ${isi.nilai})`;\n    const basi = isi.nilai; isi = { nilai: sumber(), waktu: t }; generasi++;\n    return `t=${t}s STALE -> kirim cache lama (${basi}), regenerasi di belakang -> ${isi.nilai}`;\n  };\n}\nlet harga = 45000;\nconst ambil = buatCache(60, () => harga);\nconsole.log(ambil(0)); console.log(ambil(30));\nharga = 47000;                         // admin mengubah harga\nconsole.log(ambil(45)); console.log(ambil(70)); console.log(ambil(80));","lang":"ts","out":"t=0s MISS  -> render baru (harga 45000)\nt=30s HIT   -> dari cache (harga 45000)\nt=45s HIT   -> dari cache (harga 45000)\nt=70s STALE -> kirim cache lama (45000), regenerasi di belakang -> 47000\nt=80s HIT   -> dari cache (harga 47000)"}]}},{"b":["Jika satu bagian halaman lambat (misalnya rekomendasi produk), jangan biarkan seluruh halaman menunggu. Bungkus bagian itu dengan <code>&lt;Suspense fallback={...}&gt;</code>: bagian cepat tampil dulu, bagian lambat <b>dialirkan (streaming)</b> begitu siap.","File <code>loading.tsx</code> otomatis menjadi fallback Suspense untuk seluruh halaman di folder itu. Gunakan <b>skeleton</b> yang menyerupai bentuk konten agar tata letak tidak meloncat.","Hasilnya waktu tampil pertama lebih cepat, sesuatu yang terasa jelas pada koneksi seluler yang lambat."],"lang":"tsx","code":"// app/produk/[slug]/page.tsx\nimport { Suspense } from 'react';\n\nexport default async function Detail({ params }: { params: Promise<{ slug: string }> }) {\n  const { slug } = await params;\n  const p = await ambilProduk(slug);           // cepat\n  return (\n    <main>\n      <h1>{p.nama}</h1>\n      <Suspense fallback={<div className=\"h-40 animate-pulse rounded bg-gray-200\" />}>\n        <Rekomendasi slug={slug} />            {/* lambat, dialirkan belakangan */}\n      </Suspense>\n    </main>\n  );\n}\n\nasync function Rekomendasi({ slug }: { slug: string }) {\n  const daftar = await ambilRekomendasi(slug);  // 2 detik\n  return <ul>{daftar.map((r) => <li key={r.id}>{r.nama}</li>)}</ul>;\n}","pts":["Suspense membuat bagian lambat tidak menahan halaman.","loading.tsx = fallback untuk satu folder.","Skeleton menjaga tata letak stabil."],"q":[["Manfaat streaming?",["Konten cepat tampil lebih dulu","Menghemat kuota database","Menghapus kebutuhan cache"],0,"Tidak menunggu bagian paling lambat."]],"deep":{"ist":[["Streaming SSR","Server mengirim HTML bertahap; bagian cepat tampil lebih dulu."],["loading.tsx","Fallback otomatis untuk satu segmen rute (dibungkus Suspense)."],["Suspense boundary","Batas per bagian halaman agar komponen lambat tidak menahan semuanya."],["TTFB & FCP","Time to First Byte dan First Contentful Paint membaik dengan streaming."]],"cx":[{"t":"Dasbor dengan bagian yang dimuat bertahap","code":"// app/dasbor/loading.tsx\nexport default function Loading() { return <div className=\"skeleton h-screen\" />; }\n\n// app/dasbor/page.tsx\nimport { Suspense } from \"react\";\nexport default function Dasbor() {\n  return (\n    <>\n      <h1>Ringkasan Toko</h1>                                {/* langsung tampil */}\n      <Suspense fallback={<KartuSkeleton />}><Omzet /></Suspense>          {/* 200 ms */}\n      <Suspense fallback={<TabelSkeleton />}><PesananTerbaru /></Suspense> {/* 800 ms */}\n      <Suspense fallback={<GrafikSkeleton />}><GrafikTahunan /></Suspense> {/* 2 detik */}\n    </>\n  );\n}\nasync function GrafikTahunan() {\n  const data = await laporanTahunan();     // query berat\n  return <Grafik data={data} />;\n}","lang":"tsx"},{"t":"Tanpa streaming vs dengan streaming","code":"const bagian = [[\"Header\", 0], [\"Omzet\", 200], [\"Pesanan terbaru\", 800], [\"Grafik tahunan\", 2000]] as const;\nconst tanpa = Math.max(...bagian.map(([, ms]) => ms));\nconsole.log(`Tanpa streaming: layar kosong sampai ${tanpa} ms, lalu semua muncul bersamaan`);\nconsole.log(\"Dengan streaming:\");\nfor (const [nama, ms] of bagian) console.log(`  ${String(ms).padStart(5)} ms  ${nama} tampil`);\nconsole.log(`Konten pertama ${tanpa / Math.max(1, bagian[1][1])}x lebih cepat terlihat`);","lang":"ts","out":"Tanpa streaming: layar kosong sampai 2000 ms, lalu semua muncul bersamaan\nDengan streaming:\n      0 ms  Header tampil\n    200 ms  Omzet tampil\n    800 ms  Pesanan terbaru tampil\n   2000 ms  Grafik tahunan tampil\nKonten pertama 10x lebih cepat terlihat"}]}},{"b":["<b>Server Action</b> adalah fungsi <code>async</code> bertanda <code>'use server'</code> yang bisa dipanggil langsung dari form. Tidak perlu membuat endpoint API sendiri: form mengirim data, fungsi berjalan di server, lalu panggil <code>revalidatePath</code> atau <code>redirect</code>. Form tetap bekerja walau JavaScript belum termuat.","Server Action adalah endpoint publik: <b>selalu validasi input</b> (misalnya dengan Zod) dan <b>periksa izin</b> pengguna di dalamnya. Di sisi client, <code>useActionState</code> menampilkan pesan error dan status menunggu.","<b>Route Handler</b> (<code>app/api/.../route.ts</code>) dipakai jika butuh endpoint HTTP biasa: webhook payment gateway, API untuk aplikasi mobile, atau integrasi pihak ketiga."],"lang":"ts","code":"// app/ulasan/actions.ts\n'use server';\nimport { z } from 'zod';\nimport { revalidatePath } from 'next/cache';\n\nconst Skema = z.object({\n  slug: z.string(),\n  rating: z.coerce.number().int().min(1).max(5),\n  komentar: z.string().min(5, 'Komentar minimal 5 karakter'),\n});\n\nexport async function kirimUlasan(_: unknown, form: FormData) {\n  const hasil = Skema.safeParse(Object.fromEntries(form));\n  if (!hasil.success) return { error: hasil.error.issues[0].message };\n  await db.ulasan.create({ data: hasil.data });\n  revalidatePath(`/produk/${hasil.data.slug}`);\n  return { error: null };\n}\n\n// app/api/webhook/pembayaran/route.ts\nexport async function POST(req: Request) {\n  const body = await req.json();\n  // verifikasi tanda tangan webhook dulu!\n  await tandaiLunas(body.order_id);\n  return Response.json({ ok: true });\n}","so":[{"q":"Buat form di Client Component yang memakai <code>useActionState</code> dengan action <code>kirimUlasan</code> dan menampilkan pesan error.","h":"useActionState(action, stateAwal) mengembalikan [state, formAction, pending].","a":"'use client';\nimport { useActionState } from 'react';\nimport { kirimUlasan } from './actions';\n\nexport default function FormUlasan({ slug }: { slug: string }) {\n  const [state, action, pending] = useActionState(kirimUlasan, { error: null });\n  return (\n    <form action={action}>\n      <input type=\"hidden\" name=\"slug\" value={slug} />\n      <input name=\"rating\" type=\"number\" min={1} max={5} required />\n      <textarea name=\"komentar\" />\n      {state.error && <p role=\"alert\">{state.error}</p>}\n      <button disabled={pending}>{pending ? 'Mengirim…' : 'Kirim ulasan'}</button>\n    </form>\n  );\n}","lang":"tsx"}],"pts":["'use server' untuk fungsi yang dipanggil dari form.","Validasi input dan cek izin di setiap Server Action.","Route Handler untuk webhook dan API publik."],"q":[["Kenapa Server Action tetap harus memvalidasi input?",["Siapa pun bisa memanggilnya seperti endpoint publik","Agar TypeScript tidak error","Tidak perlu validasi"],0,"Jangan percaya data dari client."]],"deep":{"ist":[["Server Action","Fungsi \"use server\" yang dipanggil dari form/klien dan berjalan di server."],["Progressive enhancement","Form dengan Server Action tetap berfungsi walau JavaScript belum dimuat."],["useActionState","Hook React 19 untuk status dan hasil sebuah action."],["Route Handler","File route.ts berisi fungsi GET/POST untuk API publik atau webhook."],["Webhook","Endpoint yang dipanggil layanan lain (misalnya payment gateway) saat ada kejadian."]],"cx":[{"t":"Form ulasan dengan Server Action dan webhook pembayaran","code":"// app/produk/[slug]/actions.ts\n\"use server\";\nimport { z } from \"zod\";\nimport { revalidatePath } from \"next/cache\";\n\nconst Ulasan = z.object({ produkId: z.coerce.number(), bintang: z.coerce.number().min(1).max(5), isi: z.string().min(10) });\n\nexport async function kirimUlasan(_: unknown, form: FormData) {\n  const user = await auth();\n  if (!user) return { error: \"Silakan masuk dulu\" };\n  const hasil = Ulasan.safeParse(Object.fromEntries(form));\n  if (!hasil.success) return { error: hasil.error.issues[0].message };\n  await db.ulasan.create({ data: { ...hasil.data, userId: user.id } });\n  revalidatePath(`/produk/${hasil.data.produkId}`);\n  return { ok: true };\n}\n\n// FormUlasan.tsx\n\"use client\";\nimport { useActionState } from \"react\";\nexport function FormUlasan({ produkId }: { produkId: number }) {\n  const [state, action, pending] = useActionState(kirimUlasan, null);\n  return (\n    <form action={action}>\n      <input type=\"hidden\" name=\"produkId\" value={produkId} />\n      <select name=\"bintang\">{[5, 4, 3, 2, 1].map((b) => <option key={b}>{b}</option>)}</select>\n      <textarea name=\"isi\" required minLength={10} />\n      <button disabled={pending}>{pending ? \"Mengirim...\" : \"Kirim ulasan\"}</button>\n      {state?.error && <p role=\"alert\">{state.error}</p>}\n    </form>\n  );\n}\n\n// app/api/webhook/pembayaran/route.ts\nexport async function POST(req: Request) {\n  const body = await req.text();\n  if (!verifikasiSignature(body, req.headers.get(\"x-signature\"))) return new Response(\"invalid\", { status: 401 });\n  const ev = JSON.parse(body);\n  if (ev.status === \"settlement\") await tandaiLunas(ev.order_id);\n  return Response.json({ diterima: true });\n}","lang":"tsx"},{"t":"Verifikasi signature webhook dengan HMAC","code":"import { createHmac, timingSafeEqual } from \"node:crypto\";\n\nconst RAHASIA = \"kunci-rahasia-dari-dashboard-payment\";\nconst tandatangan = (body: string) => createHmac(\"sha256\", RAHASIA).update(body).digest(\"hex\");\nfunction verifikasi(body: string, sig: string | null) {\n  if (!sig) return false;\n  const a = Buffer.from(tandatangan(body)), b = Buffer.from(sig);\n  return a.length === b.length && timingSafeEqual(a, b);     // tahan timing attack\n}\nconst body = JSON.stringify({ order_id: \"INV-2026-0042\", status: \"settlement\", gross_amount: \"148000\" });\nconst sigAsli = tandatangan(body);\nconsole.log(\"signature asli    :\", verifikasi(body, sigAsli) ? \"200 diterima\" : \"401 ditolak\");\nconsole.log(\"body diubah       :\", verifikasi(body.replace(\"148000\", \"1000\"), sigAsli) ? \"200 diterima\" : \"401 ditolak\");\nconsole.log(\"tanpa signature   :\", verifikasi(body, null) ? \"200 diterima\" : \"401 ditolak\");","lang":"ts","out":"signature asli    : 200 diterima\nbody diubah       : 401 ditolak\ntanpa signature   : 401 ditolak"}]}},{"b":["<code>next/image</code> otomatis mengubah ukuran gambar sesuai layar, mengirim format modern (WebP, AVIF), memuat malas (lazy) gambar di bawah layar, dan mencegah tata letak bergeser karena lebar dan tinggi sudah diketahui. Beri <code>priority</code> untuk gambar utama di atas layar agar LCP cepat.","<code>next/font</code> mengunduh font Google saat build dan menyajikannya dari domain sendiri: tidak ada permintaan ke server Google saat halaman dibuka dan tidak ada teks berkedip.","Kedua fitur ini langsung memperbaiki skor <b>Core Web Vitals</b> (LCP, CLS, INP) yang memengaruhi peringkat pencarian."],"lang":"tsx","code":"import Image from 'next/image';\nimport { Plus_Jakarta_Sans } from 'next/font/google';\n\nconst font = Plus_Jakarta_Sans({ subsets: ['latin'], weight: ['400', '700'] });\n\nexport default function Hero() {\n  return (\n    <section className={font.className}>\n      <Image\n        src=\"/kopi-gayo.jpg\"\n        alt=\"Biji kopi Gayo dalam karung goni\"\n        width={1200}\n        height={630}\n        sizes=\"(max-width: 768px) 100vw, 50vw\"\n        priority\n      />\n      <h1>Kopi Nusantara, dipanggang setiap minggu</h1>\n    </section>\n  );\n}","pts":["next/image: ukuran, format, lazy, tanpa CLS.","priority untuk gambar utama.","next/font: font disajikan sendiri."],"q":[["Atribut next/image untuk gambar hero di atas layar?",["priority","loading=\"lazy\"","unoptimized"],0,"Dimuat lebih awal untuk LCP."]],"deep":{"ist":[["next/image","Mengubah ukuran, format (WebP/AVIF), dan lazy load gambar otomatis."],["sizes & srcset","Memberi tahu browser lebar gambar di tiap breakpoint agar unduhan pas."],["priority / fetchPriority","Muat lebih dulu gambar LCP (biasanya hero)."],["next/font","Font di-self-host saat build; tanpa request ke Google, tanpa layout shift."],["CLS","Cumulative Layout Shift; width/height pada gambar mencegah konten melompat."]],"cx":[{"t":"Hero dan grid produk yang dioptimalkan","code":"import Image from \"next/image\";\nimport { Inter, Plus_Jakarta_Sans } from \"next/font/google\";\n\nconst inter = Inter({ subsets: [\"latin\"], variable: \"--font-inter\", display: \"swap\" });\nconst jakarta = Plus_Jakarta_Sans({ subsets: [\"latin\"], weight: [\"600\", \"800\"], variable: \"--font-judul\" });\n\nexport default function Beranda({ produk }: { produk: Produk[] }) {\n  return (\n    <main className={`${inter.variable} ${jakarta.variable}`}>\n      <Image src=\"/hero-kopi.jpg\" alt=\"Biji kopi Gayo disangrai\" width={1600} height={900}\n             priority sizes=\"100vw\" className=\"w-full h-auto\" />\n      <ul className=\"grid grid-cols-2 md:grid-cols-4\">\n        {produk.map((p) => (\n          <li key={p.id}>\n            <Image src={p.gambar} alt={p.nama} width={400} height={400}\n                   sizes=\"(min-width: 768px) 25vw, 50vw\" placeholder=\"blur\" blurDataURL={p.blur} />\n          </li>\n        ))}\n      </ul>\n    </main>\n  );\n}","lang":"tsx"},{"t":"Berapa byte yang dihemat oleh sizes yang tepat","code":"const lebarTersedia = [640, 750, 828, 1080, 1200, 1920];\nconst kbPerPx = (w: number) => Math.round((w * w) * 0.00009);   // perkiraan JPEG->WebP persegi\nfunction pilih(lebarTampil: number, dpr: number) {\n  const target = lebarTampil * dpr;\n  return lebarTersedia.find((w) => w >= target) ?? lebarTersedia.at(-1)!;\n}\nfor (const [perangkat, viewport, dpr] of [[\"Ponsel\", 390, 3], [\"Tablet\", 820, 2], [\"Laptop\", 1440, 1]] as const) {\n  const lebarKartu = viewport >= 768 ? viewport / 4 : viewport / 2;\n  const tanpaSizes = pilih(viewport, dpr), denganSizes = pilih(lebarKartu, dpr);\n  console.log(`${perangkat.padEnd(7)} tanpa sizes ${String(tanpaSizes).padStart(4)}px ~${String(kbPerPx(tanpaSizes)).padStart(3)} KB | dengan sizes ${String(denganSizes).padStart(4)}px ~${String(kbPerPx(denganSizes)).padStart(3)} KB`);\n}","lang":"ts","out":"Ponsel  tanpa sizes 1200px ~130 KB | dengan sizes  640px ~ 37 KB\nTablet  tanpa sizes 1920px ~332 KB | dengan sizes  640px ~ 37 KB\nLaptop  tanpa sizes 1920px ~332 KB | dengan sizes  640px ~ 37 KB"}]}},{"b":["<b>Middleware</b> (<code>middleware.ts</code> di akar proyek) berjalan sebelum request mencapai halaman. Cocok untuk mengalihkan pengguna yang belum login, mengatur bahasa, atau A/B test. Batasi dengan <code>matcher</code> agar tidak berjalan di setiap file statis.","Untuk login, pustaka populer adalah <b>Auth.js</b> (NextAuth) dengan penyedia Google, GitHub, atau email, serta layanan seperti Clerk dan Supabase Auth. Sesi disimpan di cookie yang aman (httpOnly).","Middleware hanya lapisan pertama. Tetap periksa sesi di Server Component, Server Action, dan Route Handler yang mengakses data pribadi."],"lang":"ts","code":"// middleware.ts\nimport { NextResponse, type NextRequest } from 'next/server';\n\nexport function middleware(req: NextRequest) {\n  const sesi = req.cookies.get('sesi');\n  if (!sesi) {\n    const url = new URL('/masuk', req.url);\n    url.searchParams.set('kembali', req.nextUrl.pathname);\n    return NextResponse.redirect(url);\n  }\n  return NextResponse.next();\n}\n\nexport const config = { matcher: ['/akun/:path*', '/pesanan/:path*'] };\n\n// app/pesanan/page.tsx\nimport { auth } from '@/auth';\nexport default async function Pesanan() {\n  const sesi = await auth();\n  if (!sesi) redirect('/masuk');\n  const daftar = await db.pesanan.findMany({ where: { userId: sesi.user.id } });\n  // ...\n}","pts":["Middleware berjalan sebelum halaman.","matcher membatasi rute.","Tetap cek sesi di server untuk data pribadi."],"q":[["Cukupkah melindungi data hanya dengan middleware?",["Tidak, periksa juga di Server Component dan Action","Ya, selalu cukup","Middleware tidak bisa redirect"],0,"Pertahanan berlapis."]],"deep":{"ist":[["Middleware / proxy.ts","Kode yang berjalan sebelum request mencapai halaman (Next.js 16 menamainya proxy)."],["Matcher","Pola path yang diproses middleware."],["Auth.js / Clerk / Better Auth","Pustaka autentikasi populer untuk Next.js."],["Session cookie (httpOnly)","Cookie yang tidak dapat dibaca JavaScript; melindungi dari pencurian token lewat XSS."],["Defense in depth","Cek auth di middleware dan juga di Server Component/Action, jangan hanya satu lapis."]],"cx":[{"t":"Melindungi /akun dan /admin","code":"// middleware.ts (Next.js 15) atau proxy.ts (Next.js 16)\nimport { NextResponse, type NextRequest } from \"next/server\";\n\nexport function middleware(req: NextRequest) {\n  const sesi = req.cookies.get(\"sesi\")?.value;\n  const { pathname } = req.nextUrl;\n  if (!sesi) {\n    const url = new URL(\"/masuk\", req.url);\n    url.searchParams.set(\"lanjut\", pathname);\n    return NextResponse.redirect(url);\n  }\n  const res = NextResponse.next();\n  res.headers.set(\"x-frame-options\", \"DENY\");\n  return res;\n}\nexport const config = { matcher: [\"/akun/:path*\", \"/admin/:path*\"] };\n\n// app/admin/page.tsx  -> tetap cek ulang di server\nexport default async function Admin() {\n  const user = await auth();\n  if (user?.peran !== \"admin\") redirect(\"/\");\n  return <PanelAdmin />;\n}","lang":"tsx"},{"t":"Logika matcher dan redirect","code":"const matcher = [\"/akun/:path*\", \"/admin/:path*\"];\nconst keRegex = (p: string) => new RegExp(\"^\" + p.replace(/\\/:path\\*$/, \"(/.*)?\") + \"$\");\nfunction proses(path: string, sesi?: { peran: string }) {\n  if (!matcher.some((m) => keRegex(m).test(path))) return \"lewat (publik)\";\n  if (!sesi) return `302 -> /masuk?lanjut=${encodeURIComponent(path)}`;\n  if (path.startsWith(\"/admin\") && sesi.peran !== \"admin\") return \"403 bukan admin\";\n  return \"200 lanjut ke halaman\";\n}\nconst uji: [string, { peran: string }?][] = [[\"/produk\"], [\"/akun/pesanan\"], [\"/akun\", { peran: \"user\" }], [\"/admin/laporan\", { peran: \"user\" }], [\"/admin\", { peran: \"admin\" }]];\nfor (const [p, s] of uji) console.log(p.padEnd(16), (s?.peran ?? \"tamu\").padEnd(6), \"->\", proses(p, s));","lang":"ts","out":"/produk          tamu   -> lewat (publik)\n/akun/pesanan    tamu   -> 302 -> /masuk?lanjut=%2Fakun%2Fpesanan\n/akun            user   -> 200 lanjut ke halaman\n/admin/laporan   user   -> 403 bukan admin\n/admin           admin  -> 200 lanjut ke halaman"}]}},{"b":["Simpan rahasia di <code>.env.local</code> (tidak masuk Git). Variabel biasa hanya terbaca di server. Variabel berawalan <code>NEXT_PUBLIC_</code> ikut dikirim ke browser, jadi <b>jangan pernah</b> memberi awalan itu pada kunci rahasia.","Deploy paling mudah ke <b>Vercel</b>: hubungkan repositori GitHub, setiap push ke main otomatis rilis, dan setiap pull request mendapat URL pratinjau. Alternatif: Netlify, Cloudflare, atau server sendiri dengan <code>output: 'standalone'</code> dan Docker.","Sebelum rilis jalankan <code>npm run build</code> secara lokal untuk melihat ukuran setiap rute dan mana yang statis atau dinamis."],"lang":"bash","code":"# .env.local\nDATABASE_URL=postgres://...\nAUTH_SECRET=rahasia-panjang\nNEXT_PUBLIC_SITE_URL=https://tokoku.id\n\n$ npm run build","out":"   ▲ Next.js 15.5.4\n\n ✓ Compiled successfully in 6.2s\n ✓ Generating static pages (14/14)\n\nRoute (app)                        Size  First Load JS\n┌ ○ /                             1.9 kB         110 kB\n├ ○ /produk                        2.4 kB         111 kB\n├ ● /produk/[slug]                 1.1 kB         109 kB\n├   ├ /produk/kopi-gayo\n├   └ /produk/kopi-toraja\n├ ƒ /pesanan                        980 B         108 kB\n└ ƒ /api/webhook/pembayaran          0 B            0 B\n\n○  (Static)   prerendered as static content\n●  (SSG)      prerendered as static HTML (uses generateStaticParams)\nƒ  (Dynamic)  server-rendered on demand","run":false,"pts":["NEXT_PUBLIC_ = terlihat di browser.","Vercel: push otomatis rilis, PR dapat pratinjau.","npm run build menunjukkan rute statis dan dinamis."],"q":[["Variabel yang aman untuk kunci API payment gateway?",["PAYMENT_SECRET_KEY","NEXT_PUBLIC_PAYMENT_KEY","Ditulis langsung di komponen"],0,"Tanpa awalan NEXT_PUBLIC_."]],"deep":{"ist":[[".env.local","File variabel lingkungan lokal; tidak boleh di-commit."],["NEXT_PUBLIC_","Prefiks untuk variabel yang boleh terlihat di browser; selain itu hanya di server."],["Preview deployment","Setiap pull request mendapat URL sendiri untuk direview (Vercel, Netlify)."],["output: \"standalone\"","Build mandiri untuk Docker/VPS tanpa node_modules penuh."],["Edge vs Node runtime","Edge lebih cepat start dan dekat pengguna, tetapi API Node terbatas."]],"cx":[{"t":"Konfigurasi env dan Docker","code":"# .env.local  (JANGAN di-commit; tambahkan ke .gitignore)\nDATABASE_URL=\"postgresql://user:pass@localhost:5432/toko\"\nMIDTRANS_SERVER_KEY=\"SB-Mid-server-xxx\"          # rahasia: hanya server\nNEXT_PUBLIC_SITE_URL=\"https://toko.example.id\"    # aman tampil di browser\n\n# Validasi env saat start (src/env.ts)\nimport { z } from \"zod\";\nexport const env = z.object({\n  DATABASE_URL: z.string().url(),\n  MIDTRANS_SERVER_KEY: z.string().min(10),\n  NEXT_PUBLIC_SITE_URL: z.string().url(),\n}).parse(process.env);\n\n# next.config.ts\nexport default { output: \"standalone\", images: { remotePatterns: [{ hostname: \"cdn.toko.id\" }] } };\n\n# Dockerfile (ringkas)\nFROM node:22-alpine AS build\nWORKDIR /app\nCOPY . .\nRUN npm ci && npm run build\nFROM node:22-alpine\nWORKDIR /app\nCOPY --from=build /app/.next/standalone ./\nCOPY --from=build /app/.next/static ./.next/static\nCOPY --from=build /app/public ./public\nCMD [\"node\", \"server.js\"]","lang":"bash"},{"t":"Memeriksa env sebelum deploy","code":"const env: Record<string, string | undefined> = {\n  DATABASE_URL: \"postgresql://user:pass@db:5432/toko\",\n  NEXT_PUBLIC_SITE_URL: \"https://toko.example.id\",\n  NEXT_PUBLIC_MIDTRANS_SERVER_KEY: \"SB-Mid-server-abc123\",\n  SENTRY_DSN: undefined,\n};\nconst wajib = [\"DATABASE_URL\", \"NEXT_PUBLIC_SITE_URL\", \"SENTRY_DSN\"];\nconst kataRahasia = /SECRET|SERVER_KEY|PASSWORD|TOKEN|PRIVATE/;\nfor (const k of wajib) if (!env[k]) console.log(`✗ ${k} belum diisi`);\nfor (const k of Object.keys(env))\n  if (k.startsWith(\"NEXT_PUBLIC_\") && kataRahasia.test(k)) console.log(`✗ ${k}: rahasia akan bocor ke browser, hapus prefiks NEXT_PUBLIC_`);\nconst url = env.NEXT_PUBLIC_SITE_URL ?? \"\";\nconsole.log(url.startsWith(\"https://\") ? \"✓ SITE_URL memakai HTTPS\" : \"✗ SITE_URL harus HTTPS\");","lang":"ts","out":"✗ SENTRY_DSN belum diisi\n✗ NEXT_PUBLIC_MIDTRANS_SERVER_KEY: rahasia akan bocor ke browser, hapus prefiks NEXT_PUBLIC_\n✓ SITE_URL memakai HTTPS"}]}},{},{},{},{},{},{},{},{},{},{},{},{},{},{}]);
